package cn.workbench;
import org.springframework.stereotype.Component;import java.util.*;import java.time.*;import java.sql.Timestamp;
@Component public class Records {
 final Store db;final Jsons json;public Records(Store s,Jsons j){db=s;json=j;}
 static final Map<String,String> TABLE=Map.ofEntries(Map.entry("COMPANY","company"),Map.entry("DEPARTMENT","department"),Map.entry("TASK","task"),Map.entry("SUB_TASK","sub_task"),Map.entry("DEADLINE_CHANGE","task_deadline_history"),Map.entry("COMMENT","task_comment"),Map.entry("PROGRESS","task_progress"),Map.entry("DEADLINE_REQUEST","deadline_request"),Map.entry("COLLABORATION_REQUEST","collaboration_request"),Map.entry("RESULT_VERSION","result_version"),Map.entry("TAG","function_tag"),Map.entry("RULE","matching_rule"),Map.entry("MATCHING_FEEDBACK","matching_feedback"),Map.entry("CHANNEL","notification_channel"),Map.entry("KPI_TEMPLATE","kpi_template"),Map.entry("KPI_RUN","kpi_run"),Map.entry("KPI_SCORE","kpi_score"),Map.entry("KPI_APPEAL","kpi_appeal"),Map.entry("KPI_ADJUSTMENT","kpi_adjustment"),Map.entry("ATTACHMENT","attachment"));
 static final Map<String,String> FIELDS=Map.ofEntries(Map.entry("COMPANY","name enabled companyCode"),Map.entry("DEPARTMENT","companyId name enabled"),Map.entry("TASK","companyId hostDeptId creatorId code title content priority status deadline originalDeadline everOverdue summarizedAt acceptedAt"),Map.entry("SUB_TASK","taskId companyId deptId ownerId isHost status deadline originalDeadline everOverdue rejectCount firstReceivedAt submittedAt"),Map.entry("DEADLINE_CHANGE","taskId subTaskId previousDeadline currentDeadline reason actorId"),Map.entry("COMMENT","taskId authorId content"),Map.entry("PROGRESS","taskId subTaskId authorId percent note"),Map.entry("DEADLINE_REQUEST","taskId subTaskId requestedDeadline reason status"),Map.entry("COLLABORATION_REQUEST","taskId deptId companyId status"),Map.entry("RESULT_VERSION","taskId subTaskId summary revision"),Map.entry("TAG","companyId deptId name weight"),Map.entry("RULE","companyId name ruleVersion"),Map.entry("MATCHING_FEEDBACK","taskId reason"),Map.entry("CHANNEL","companyId name enabled"),Map.entry("KPI_TEMPLATE","name templateVersion approved weightsJson"),Map.entry("KPI_RUN","companyId period templateId simulation publishedAt lockedAt inputSnapshot"),Map.entry("KPI_SCORE","runId deptId rawScore adjustedScore metricsJson"),Map.entry("KPI_APPEAL","scoreId applicantId reason decision"),Map.entry("KPI_ADJUSTMENT","scoreId actorId score reason"),Map.entry("ATTACHMENT","taskId subTaskId uploaderId storageKey originalName mimeType sizeBytes sha256 scanStatus"));
 public Map<String,Object> create(String kind,int company,Integer dept,Long task,Long owner,String status,Map<String,Object> payload){Map<String,Object> r=new LinkedHashMap<>();r.put("kind",kind);r.put("companyId",company);r.put("deptId",dept);r.put("taskId",task);r.put("ownerId",owner);r.put("status",status);r.put("payload",json.write(payload));db.insert(r);r.put("version",0);var value=view(r,false);if(TABLE.containsKey(kind))db.insertProjection(TABLE.get(kind),projection(kind,value));return get(Jsons.number(r.get("id")));}
 public Map<String,Object> get(long id){var row=db.record(id);if(row==null)throw new ApiException(404,"NOT_FOUND","记录不存在");return view(row,true);}
 public Map<String,Object> lock(long id){var row=db.lock(id);if(row==null)throw new ApiException(404,"NOT_FOUND","记录不存在");return view(row,true);}
 public Map<String,Object> view(Map<String,Object> row,boolean typed){Map<String,Object> m=json.map(String.valueOf(row.get("payload")));m.putAll(row);m.remove("payload");String kind=String.valueOf(row.get("kind"));if(typed&&TABLE.containsKey(kind)){var p=db.projection(TABLE.get(kind),Jsons.number(row.get("id")));if(p==null)throw new IllegalStateException("Missing relational entity "+kind);m.putAll(p);}if(kind.equals("SUB_TASK"))m.put("userIds",db.assignees(Jsons.number(row.get("id"))));return m;}
 public void save(Map<String,Object> value){Map<String,Object> r=new LinkedHashMap<>(value);r.put("payload",json.write(value));if(db.update(r)!=1)throw ApiException.conflict();String kind=String.valueOf(value.get("kind"));if(TABLE.containsKey(kind))db.updateProjection(TABLE.get(kind),projection(kind,value));value.put("version",Jsons.integer(value.get("version"))+1);}
 public List<Map<String,Object>> list(String kind,Integer company,Integer dept){return db.list(kind,company,dept).stream().map(r->view(r,true)).toList();}
 public List<Map<String,Object>> children(long task,String kind){return db.children(task,kind).stream().map(r->view(r,true)).toList();}
 static Map<String,Object> projection(String kind,Map<String,Object> m){Map<String,Object> out=new LinkedHashMap<>();out.put("id",m.get("id"));for(String k:FIELDS.get(kind).split(" ")){Object value=m.get(k);if(k.equals("companyId")&&Set.of("TAG","RULE").contains(kind)&&value instanceof Number n&&n.intValue()==0)value=null;if(k.endsWith("At")||k.equals("deadline")||k.endsWith("Deadline"))value=value==null?null:Timestamp.from(instant(value));out.put(k.replaceAll("([A-Z])","_$1").toLowerCase(),value);}return out;}
 public static Instant instant(Object value){if(value instanceof Timestamp t)return t.toInstant();if(value instanceof java.time.LocalDateTime t)return t.atZone(ZoneId.of("Asia/Shanghai")).toInstant();if(value instanceof Instant t)return t;return Instant.parse(value.toString());}
 public static Map<String,Object> map(Object... kv){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<kv.length;i+=2)m.put((String)kv[i],kv[i+1]);return m;}
}
